<style>
.mofa{--ink:#172554;--line:#dbe3ec;--blue:#3b82f6;--green:#047857;color:#334155}.mofa h1,.mofa h2{color:var(--ink)}.mofa button,.mofa a,.mofa input,.mofa select,.mofa textarea{outline-offset:3px}.mofa :focus-visible{outline:2px solid var(--blue)}.mf-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:7px 13px;border:1px solid var(--line);border-radius:7px;background:white;font-size:13px;font-weight:600;color:#334155}.mf-primary{background:var(--green);border-color:var(--green);color:white}.mf-btn:hover{box-shadow:0 2px 6px #17255415}.mf-input{width:100%;min-height:38px;border:1px solid #cbd5e1;border-radius:6px;padding:7px 10px;background:white;color:#1e293b;font-size:14px}.mf-label{display:block;margin-bottom:6px;font-size:13px;font-weight:600}.mf-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.mf-card{border:1px solid var(--line);border-radius:10px;background:white;padding:14px}.mf-table{width:100%;border-collapse:collapse;font-size:12px;line-height:1.35}.mf-table th{background:#eef2f7;text-align:left;color:#334155;font-weight:600;font-size:11px;padding:7px 6px;white-space:nowrap;vertical-align:bottom}.mf-table td{border-bottom:.5px solid var(--line);padding:6px 6px;vertical-align:middle;color:#334155}.mf-table .mf-sub{display:block;margin-top:1px;color:#64748b;font-weight:400}.mf-table th .mf-sub{color:#64748b;font-weight:500}.mf-table .mf-nw{white-space:nowrap}.mf-table .mf-text{max-width:130px;overflow-wrap:anywhere}.mf-table .mf-name{min-width:150px;max-width:190px}.mf-table .mf-strong{font-weight:600;color:#1e293b}.mf-table .mf-c{text-align:center}.mf-table .mf-r{text-align:right}.mf-table .mf-sl{color:#64748b;width:28px}.mf-table .mf-name .mf-badge{display:table;margin-top:3px}.mf-table tbody tr:nth-child(even){background:#f8fafc}.mf-table tbody tr:hover{background:#eff6ff}.mf-badge{display:inline-block;margin-top:5px;padding:1px 6px;border-radius:5px;font-size:10.5px;font-weight:600}.mf-active{background:#d1fae5;color:#065f46}.mf-expired{background:#fee2e2;color:#991b1b}.mf-expiring{background:#fef3c7;color:#92400e}.mf-processing{background:#dbeafe;color:#1e40af}.mf-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.mf-error{color:#b91c1c;font-size:12px;margin-top:4px}.mf-input[aria-invalid=true]{border-color:#ef4444}.mf-input[readonly]{background:#f1f5f9}.mf-actions{display:grid;grid-template-columns:repeat(2,28px);gap:2px;justify-content:end}.mf-actions a,.mf-actions button{width:28px;height:28px;display:grid;place-items:center;border-radius:6px}.mf-actions a:hover,.mf-actions button:hover{background:#e2e8f0}@media(max-width:1199px){.mf-grid,.mf-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.mf-grid,.mf-form-grid{grid-template-columns:1fr}}
</style>